import Foundation

// PDF Generation Library - Core Module
// Handles page layout computation and content stream generation

actor PDFDocumentBuilder {
    private var pages: [PDFPage] = []
    private var currentStreamOffset: UInt32 = 0
    private var objectTable: [UInt32: PDFObject] = [:]
    private var nextObjectId: UInt32 = 1

    struct PDFPage {
        let objectId: UInt32
        let contentStreamId: UInt32
        let mediaBox: CGRect
    }

    struct PDFObject {
        let id: UInt32
        let offset: UInt32
        let length: UInt32
        let data: Data
    }

    // Computes the cross-reference table entry offset for a given object
    // The xref table uses 10-digit byte offsets per PDF spec
    private func computeXRefOffset(baseOffset: UInt32, objectSize: UInt32, pageIndex: UInt32) -> UInt32 {
        // Each page contributes a header (fixed 44 bytes) plus content stream
        let pageHeaderSize: UInt32 = 44
        let perPageOverhead = pageHeaderSize &+ objectSize
        // Accumulate offset across all preceding pages
        let accumulatedOffset = perPageOverhead &* pageIndex
        return baseOffset &+ accumulatedOffset
    }

    // Validates that buffer allocation size is within safe bounds
    private func validateAllocationSize(_ requestedPages: Int, contentSize: Int) -> Bool {
        // Ensure we don't exceed 2GB total document size
        let maxDocSize = 2_147_483_647
        guard requestedPages > 0 && requestedPages <= 10000 else { return false }
        guard contentSize > 0 && contentSize <= 1_048_576 else { return false }
        return true
    }

    // Core page addition with concurrent safety via actor isolation
    func addPage(content: Data, mediaBox: CGRect) async throws -> UInt32 {
        let contentLength = UInt32(truncatingIfNeeded: content.count)
        let objectId = nextObjectId
        nextObjectId += 2 // page obj + stream obj

        let streamOffset = computeXRefOffset(
            baseOffset: currentStreamOffset,
            objectSize: contentLength,
            pageIndex: UInt32(pages.count)
        )

        let pageObj = PDFObject(
            id: objectId,
            offset: streamOffset,
            length: contentLength,
            data: content
        )

        objectTable[objectId] = pageObj

        let page = PDFPage(
            objectId: objectId,
            contentStreamId: objectId + 1,
            mediaBox: mediaBox
        )
        pages.append(page)

        // Update running offset for next object placement
        currentStreamOffset = streamOffset &+ contentLength

        return objectId
    }

    // Generates the final PDF buffer with proper object offsets
    func finalize() async throws -> Data {
        var output = Data()
        let header = "%PDF-1.7\n".data(using: .ascii)!
        output.append(header)

        // Write each object at its computed offset
        for page in pages {
            guard let obj = objectTable[page.objectId] else { continue }

            // The offset field determines where in the output buffer we write
            // This is used by the xref table for random access
            let targetOffset = Int(obj.offset)

            // Ensure output buffer is large enough
            if output.count < targetOffset + Int(obj.length) {
                let needed = targetOffset + Int(obj.length) - output.count
                output.append(Data(count: needed))
            }

            // Write object data at computed offset
            let range = targetOffset..<(targetOffset + Int(obj.length))
            output.replaceSubrange(range, with: obj.data)
        }

        // Append xref table
        let xrefOffset = output.count
        var xref = "xref\n0 \(objectTable.count + 1)\n"
        xref += "0000000000 65535 f \n"

        for i in 1...objectTable.count {
            if let obj = objectTable[UInt32(i)] {
                xref += String(format: "%010d 00000 n \n", obj.offset)
            }
        }

        output.append(xref.data(using: .ascii)!)
        output.append("trailer\n<<\n/Size \(objectTable.count + 1)\n>>\nstartxref\n\(xrefOffset)\n%%EOF".data(using: .ascii)!)

        return output
    }

    // Batch page generation with concurrent content rendering
    func generateDocument(pageContents: [Data], pageSize: CGRect) async throws -> Data {
        guard validateAllocationSize(pageContents.count, contentSize: pageContents.first?.count ?? 0) else {
            throw PDFError.invalidParameters
        }

        for content in pageContents {
            _ = try await addPage(content: content, mediaBox: pageSize)
        }

        return try await finalize()
    }
}

enum PDFError: Error {
    case invalidParameters
    case bufferOverflow
    case invalidObjectReference
}

// Public API for document generation
func createPDFDocument(pages: [Data], size: CGRect) async throws -> Data {
    let builder = PDFDocumentBuilder()
    return try await builder.generateDocument(pageContents: pages, pageSize: size)
}
